package app.layan.test;
import android.app.*;import android.media.*;import android.os.*;import java.util.*;
/** Runs in a separate package so the release can start cold at the real alarm deadline. */
public final class DhikrProbe extends Instrumentation {
 Bundle args;volatile long started,stopped;volatile int observed;HandlerThread thread;
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 public void onStart(){Bundle out=new Bundle();AudioManager audio=getContext().getSystemService(AudioManager.class);thread=new HandlerThread("playback-observer");thread.start();AudioManager.AudioPlaybackCallback cb=new AudioManager.AudioPlaybackCallback(){public void onPlaybackConfigChanged(List<AudioPlaybackConfiguration> configs){boolean active=false;for(AudioPlaybackConfiguration p:configs)if(p.getAudioAttributes().getUsage()==AudioAttributes.USAGE_MEDIA&&p.getAudioAttributes().getContentType()==AudioAttributes.CONTENT_TYPE_SPEECH)active=true;long now=SystemClock.elapsedRealtime();if(active&&getContext().getSystemService(AudioManager.class).isMusicActive()&&started==0){started=now;observed++;}if(!active&&started!=0&&stopped==0)stopped=now;}};
 try{out.putInt("ringer",audio.getRingerMode());out.putInt("audioMode",audio.getMode());out.putInt("interruptionFilter",getContext().getSystemService(NotificationManager.class).getCurrentInterruptionFilter());audio.registerAudioPlaybackCallback(cb,new Handler(thread.getLooper()));long timeout=Long.parseLong(args.getString("timeout","45000"));long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end&&stopped==0){boolean music=audio.isMusicActive();long now=SystemClock.elapsedRealtime();if(music&&started==0){started=now;observed++;}if(!music&&started!=0&&stopped==0)stopped=now;SystemClock.sleep(20);}if(started==0)throw new AssertionError("No native MEDIA/SPEECH playback observed in "+timeout+"ms");if(stopped==0)throw new AssertionError("Audio did not stop/release");out.putString("result","PASS actual native audio playback and completion");out.putLong("started",started);out.putLong("stopped",stopped);out.putLong("duration",stopped-started);finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}finally{audio.unregisterAudioPlaybackCallback(cb);thread.quitSafely();}}
}
